def _o18_union_product(a, b):
    key = (int(a.shape[0]), int(a.shape[1]), int(b.shape[1]))
    options = _O18_UNION_RULES.get(key, ()) if _SMX_ON else ()
    for gain, cost, plan in options:
        if cost <= _O18_PEEL_STATE['left']:
            _O18_PEEL_STATE['left'] -= cost
            _O18_PEEL_STATE['push'] += 1
            _O18_PEEL_STATE['selected'].append((key, cost, plan[2:5]))
            return _peel_product(a, b, plan)
    if options:
        _O18_PEEL_STATE['rejected'] += 1
    return _mm(a, b)

def _astra_bcc_newborn_impl(w, p, previous, newborn):
    if newborn is None:
        return _JUN_PARENT_NEWBORN(w, p, previous, newborn)
    old_columns, selected, base, t, s = newborn
    m, k = int(w.shape[1]), int(previous.shape[0])
    n, q = int(old_columns), int(base.shape[1])
    key = (m, k, n, q)
    if (int(p.shape[0]) != k
            or not _AB_ON or not _WINOGRAD or _SCRATCH is None
            or str(w.dtype) != 'float32' or str(p.dtype) != 'float32'
            or str(base.dtype) != 'float32'):
        return _JUN_PARENT_NEWBORN(w, p, previous, newborn)
    hold = _E2Hold()
    wp = _xsg_rows(5154, w, previous).T
    prior = p[:, :n]
    common_rhs = _xsg_rows(5159, base, previous)
    rhs = fnp.concatenate((prior, common_rhs), axis=1)
    product = _o18_union_product(wp, rhs)
    inherited = product[:, :n]
    common = fnp.copy(product[:, n:])
    _PHYS_HANDLES['newborn_common'] = common
    directions = _xsg_rows(5161, w, selected).T
    answer = fnp.empty((m, n + 2 * q), dtype=fnp.float32)
    hold.append(fnp.copyto(answer[:, :n], inherited))
    hold.append(fnp.add(common, directions * t, out=answer[:, n:n + q]))
    hold.append(fnp.add(common, directions * s, out=answer[:, n + q:]))
    _ASTRA_BCC_STATS['newborn_elements'] += 2 * m * q
    _JUN_STATS['calls'] += 1
    _JUN_STATS['shapes'].append(key)
    return answer

def _o18_union_predict(self, mlp, budget):
    _O18_PEEL_STATE.update(left=500, push=0, read=0, rejected=0, selected=[])
    return _O18_UNION_PARENT_PREDICT(self, mlp, budget)

Estimator.predict = _o18_union_predict
